"use client"; import {useState} from "react";
export default function Register(){const[done,setDone]=useState("");async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch("/api/accounts",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)});const d=await r.json();setDone(r.ok?`Account created. Assigned account number: ${d.accountNumber}`:d.error)}return <main className="container form"><div className="card"><h1>Open your account</h1><p className="muted">Submit the form and the system automatically assigns a unique account number.</p>{done&&<div className="notice">{done}</div>}<form onSubmit={submit}>{[["First name","firstName"],["Last name","lastName"],["Email","email"],["Phone","phone"]].map(x=><div key={x[1]}><label className="label">{x[0]}</label><input className="input" name={x[1]} required={x[1]!=="phone"} type={x[1]==="email"?"email":"text"}/></div>)}<label className="label">Password</label><input className="input" name="password" type="password" minLength={8} required/><button className="btn btn-primary">Create account</button></form></div></main>}